public class InnerCapacityProviderInstanceRequirementsRequestFactory(Action<Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest> factoryAction = null) : SubResourceFactory<Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest>
{

    internal InnerCapacityProviderNetworkInterfaceCountRequestFactory NetworkInterfaceCountFactory { get; set; }

    internal InnerCapacityProviderMemoryGiBPerVCpuRequestFactory MemoryGiBPerVCpuFactory { get; set; }

    internal InnerCapacityProviderVCpuCountRangeRequestFactory VCpuCountFactory { get; set; }

    internal InnerCapacityProviderNetworkBandwidthGbpsRequestFactory NetworkBandwidthGbpsFactory { get; set; }

    internal InnerCapacityProviderAcceleratorCountRequestFactory AcceleratorCountFactory { get; set; }

    internal InnerCapacityProviderBaselineEbsBandwidthMbpsRequestFactory BaselineEbsBandwidthMbpsFactory { get; set; }

    internal InnerCapacityProviderAcceleratorTotalMemoryMiBRequestFactory AcceleratorTotalMemoryMiBFactory { get; set; }

    internal InnerCapacityProviderMemoryMiBRequestFactory MemoryMiBFactory { get; set; }

    internal InnerCapacityProviderTotalLocalStorageGBRequestFactory TotalLocalStorageGBFactory { get; set; }

    protected override Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest Create()
    {
        var instanceRequirementsRequestResult = CreateInstanceRequirementsRequest();
        factoryAction?.Invoke(instanceRequirementsRequestResult);

        return instanceRequirementsRequestResult;
    }

    private Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest CreateInstanceRequirementsRequest()
    {
        var instanceRequirementsRequestResult = new Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest();

        return instanceRequirementsRequestResult;
    }
    public override void CreateChildren(Humidifier.ECS.CapacityProviderTypes.InstanceRequirementsRequest result)
    {
        base.CreateChildren(result);

        result.NetworkInterfaceCount ??= NetworkInterfaceCountFactory?.Build();
        result.MemoryGiBPerVCpu ??= MemoryGiBPerVCpuFactory?.Build();
        result.VCpuCount ??= VCpuCountFactory?.Build();
        result.NetworkBandwidthGbps ??= NetworkBandwidthGbpsFactory?.Build();
        result.AcceleratorCount ??= AcceleratorCountFactory?.Build();
        result.BaselineEbsBandwidthMbps ??= BaselineEbsBandwidthMbpsFactory?.Build();
        result.AcceleratorTotalMemoryMiB ??= AcceleratorTotalMemoryMiBFactory?.Build();
        result.MemoryMiB ??= MemoryMiBFactory?.Build();
        result.TotalLocalStorageGB ??= TotalLocalStorageGBFactory?.Build();
    }

} // End Of Class

